          "sampleSolution": "import java.io.*;\nimport java.util.*;\n//-------------------------------------------------------------------------------\npublic class Graph {\n    int [][] a; \n    int n;\n    char v[];\n    int deg[];\n    Graph() {\n        v = \"ABCDEFGHIJKLMNOP\".toCharArray();\n        deg = new int[20];\n        a = new int[20][20];\n        n = 0;\n    }\n\n    //Load data from file\n    void loadData(int k) {\n    RandomAccessFile f;int i,j,x;\n        String s;StringTokenizer t;\n        a = new int[20][20];\n        try{\n            f = new RandomAccessFile(\"data.txt\",\"r\");\n            for(i = 0; i < k; i++) \n                f.readLine();//ignores the first k-1 lines\n            \n            s = f.readLine();//just use the data in the k-th line\n            s = s.trim();\n            n = Integer.parseInt(s);\n            for(i = 0; i < n; i++) {\n                s = f.readLine();\n                s = s.trim();\n                t = new StringTokenizer(s);\n                for(j = 0; j < n; j++) { \n                    x = Integer.parseInt(t.nextToken().trim());\n                    a[i][j] = x;\n                }\n            }\n            \n            f.close();\n        }catch(Exception e) {}\n    }\n\n    void dispAdj() {\n        int i,j;\n        for(i = 0; i < n; i++) {\n            System.out.println();\n            for(j = 0; j < n; j++)\n                System.out.printf(\"%4d\",a[i][j]);\n        }\n    }\n\n    void fvisit(int i, RandomAccessFile f) throws Exception {\n        f.writeBytes(\"  \" + v[i]);\n    }\n\n    void fdispAdj(RandomAccessFile f) throws Exception { \n        int i,j;\n        f.writeBytes(\"n = \"+n+\"\\r\\n\");\n        for(i = 0; i < n; i++) {\n            f.writeBytes(\"\\r\\n\");\n            for(j = 0; j < n; j++) \n                f.writeBytes(\"  \" + a[i][j]);\n        }\n        f.writeBytes(\"\\r\\n\");\n    }\n\n    // bread first traverse from vertex k  \n    void breadth(int k, RandomAccessFile f) throws Exception {\n        Queue q = new Queue();\n        int i,h;\n        boolean [] enqueued = new boolean[n];\n        for(i = 0; i < n; i++) \n            enqueued[i] = false;\n        \n        q.enqueue(k);\n        enqueued[k] = true;\n        \n        while(!q.isEmpty()){\n            h = q.dequeue();\n            fvisit(h, f); \n            \n            for(i = 0; i < n; i++)\n                if(!enqueued[i] && a[h][i] > 0) {\n                    q.enqueue(i);\n                    enqueued[i] = true;\n                }\n        }\n\n        System.out.println();\n    }\n\n    // breadth first traverse from vertex k, only display the vertices right after k\n    // up to the next 5 vertices (i.e. the 2nd through 6th visited vertex)\n    void breadthWithConstraint(int k, RandomAccessFile f) throws Exception {\n        Queue q = new Queue();\n        int i,h,count = 0;\n        boolean [] enqueued = new boolean[n];\n        for(i = 0; i < n; i++)\n            enqueued[i] = false;\n\n        q.enqueue(k);\n        enqueued[k] = true;\n\n        while(!q.isEmpty()){\n            h = q.dequeue();\n            count++;\n            if(count >= 2 && count <= 6)\n                fvisit(h, f);\n\n            for(i = 0; i < n; i++)\n                if(!enqueued[i] && a[h][i] > 0) {\n                    q.enqueue(i);\n                    enqueued[i] = true;\n                }\n        }\n    }\n\n    void depth_rec(boolean [] visited,int k, RandomAccessFile f) throws Exception {\n        fvisit(k,f);\n        visited[k] = true;\n        for(int i = 0; i < n; i++) {\n            if(!visited[i] && a[k][i]>0) \n                depth_rec(visited,i,f);\n        }\n    }\n    \n    void depth(int k, RandomAccessFile f) throws Exception {\n        boolean [] visited = new boolean[20];\n        int i;\n        for(i = 0; i < n; i++) \n            visited[i] = false;\n        depth_rec(visited,k,f);\n        for(i = 0; i < n; i++) \n            if(!visited[i]) \n                depth_rec(visited,i,f);\n    }\n\n    // This method is used for Question 3.1\n    void f1() throws Exception {\n        loadData(1);\n        String fname = \"f1.txt\";\n        File g123 = new File(fname);\n        if(g123.exists()) g123.delete();\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\"); \n        breadth(2,f);\n        f.writeBytes(\"\\r\\n\");\n        /**\n         * Question 3.1: Perform breadth-first search on the graph.\n         * Starting from the vertex C (which index is 2), ONLY display the vertex right after C up to the next 5 vertices. \n         * Hint: copy breadth(...) to breadth_With_Constraint(...) and modify it appropriately.\n         * The output f1() will be written into file 'f1.txt'. \n         * Therefore you should open this file to see/test your code output.\n         * Example: With the graph provided in 'data.txt', the content of 'f1.txt' after running this method is \n         *          C  A  F  B  D  H  E  G  I\n         *          A  F  B  D  H\n         */\n        //---------------------------------------------------------------------------------------\n        //------ Start your code here------------------------------------------------------------\n        breadthWithConstraint(2, f);\n\n        //------ End your code here--------------------------------------------------------------\n        //---------------------------------------------------------------------------------------\n        \n        f.writeBytes(\"\\r\\n\");\n        f.close();\n    }\n\n    void f2() throws Exception {\n        loadData(1);\n        String fname = \"f2.txt\";\n        File g123 = new File(fname);\n        if(g123.exists()) g123.delete();\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\"); \n        f.writeBytes(\"\\r\\n\");\n        /**\n         * Question 3.2: Perform depth-first search on the graph.\n         * Starting from the fifth vertex (vertex E which index is 4). \n         * Hint: you just call the function 'depth()' appropriately. This function is provided above\n         * The output f2() will be written into the file 'f2.txt'. \n         * Therefore you should open this file to see/test your code output.\n         * Example: With the graph provided in 'data.txt', the content of 'f2.txt' after running this method is \n         *          E  B  A  C  F  H  I  G  D\n         */\n        //---------------------------------------------------------------------------------------\n        //------ Start your code here------------------------------------------------------------\n        depth(4, f);\n\n        //------ End your code here--------------------------------------------------------------\n        //---------------------------------------------------------------------------------------\n        f.writeBytes(\"\\r\\n\");\n        f.close();\n    }\n    \n  \n}\n",
